//! The app icon and logo, rendered from the embedded SVGs in `assets/icon/`
//! (generated by `assets/icon/build.py`). Packaged icons (.ico, .icns, the
//! Linux icon theme) are rasterised from the same sources.

use egui::{Color32, ColorImage, Rect, TextureHandle, TextureOptions, Ui};

/// The app icon: the full design on its tile, filling the square.
pub const ICON: &str = include_str!("../assets/icon/photo-airt.svg");
/// The app icon with the margin macOS icons keep around their tile.
pub const ICON_MACOS: &str = include_str!("../assets/icon/photo-airt-macos.svg");
/// The bolder cut of the icon for 32 px and below.
pub const ICON_SMALL: &str = include_str!("../assets/icon/photo-airt-small.svg");
/// The logo: the icon's artwork without the tile.
pub const MARK: &str = include_str!("../assets/icon/mark.svg");
/// The logo's bolder cut for small sizes.
pub const MARK_SMALL: &str = include_str!("../assets/icon/mark-small.svg");

/// Below this many physical pixels the small cut reads better than the full design.
const SMALL_CUT_PX: u32 = 40;

/// Rasterises an SVG to a square image of `px` pixels.
pub fn render(svg: &str, px: u32) -> Option<ColorImage> {
    let tree = resvg::usvg::Tree::from_str(svg, &resvg::usvg::Options::default()).ok()?;
    let mut pixmap = resvg::tiny_skia::Pixmap::new(px, px)?;
    let s = tree.size();
    let tf = resvg::tiny_skia::Transform::from_scale(px as f32 / s.width(), px as f32 / s.height());
    resvg::render(&tree, tf, &mut pixmap.as_mut());
    Some(ColorImage::from_rgba_premultiplied([px as usize, px as usize], pixmap.data()))
}

/// The window icon. Windows only ever shows it at 16 to 48 px (title bar,
/// taskbar, Alt+Tab), so it gets the small cut; the macOS Dock and X11 get
/// the full design.
pub fn window_icon() -> egui::IconData {
    let (svg, px) = if cfg!(windows) {
        (ICON_SMALL, 256)
    } else if cfg!(target_os = "macos") {
        (ICON_MACOS, 512)
    } else {
        (ICON, 512)
    };
    let image = render(svg, px).expect("the embedded icon renders");
    let rgba = image.pixels.iter().flat_map(|c| c.to_srgba_unmultiplied()).collect();
    egui::IconData { rgba, width: px, height: px }
}

/// Paints the logo into `rect`, rasterised once per physical size.
pub fn paint_mark(ui: &Ui, rect: Rect, tint: Color32) {
    let px = (rect.width().max(rect.height()) * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    let id = egui::Id::unique(("photo-airt-mark", px));
    let texture = ui.ctx().data_mut(|d| d.get_temp::<TextureHandle>(id)).or_else(|| {
        let svg = if px < SMALL_CUT_PX { MARK_SMALL } else { MARK };
        let texture = ui.ctx().load_texture(format!("photo-airt-mark-{px}"), render(svg, px)?, TextureOptions::LINEAR);
        ui.ctx().data_mut(|d| d.insert_temp(id, texture.clone()));
        Some(texture)
    });
    if let Some(texture) = texture {
        egui::Image::new(&texture).tint(tint).paint_at(ui, rect);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_source_renders() {
        for svg in [ICON, ICON_SMALL, ICON_MACOS, MARK, MARK_SMALL] {
            let image = render(svg, 64).expect("renders");
            assert_eq!(image.size, [64, 64]);
            // Something is drawn, and the corners of the icon stay transparent.
            assert!(image.pixels.iter().any(|c| c.a() > 200));
            assert_eq!(image.pixels[0].a(), 0);
        }
    }

    #[test]
    fn window_icon_matches_its_size() {
        let icon = window_icon();
        assert_eq!(icon.rgba.len(), (icon.width * icon.height * 4) as usize);
    }
}
